package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Refuse an edit into a correction unless the number it names is a SETTLED claim of the claim's person. */
public class RefuseInvalidCorrectionEdit {
    public void refuse(@Val ClaimInput input, @Val Claim loaded, ClaimRepository repository)
            throws InvalidClaimException {
        if (input.corrects() != null
                && !repository.settledNumbered(loaded.sheetId(), loaded.personId(), input.corrects())) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person; there is no SETTLED claim "
                    + input.corrects() + " of this person.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Refuse an edit of a claim whose editor another user holds open (locked). */
public class RefuseLockedClaimEdit {
    public void refuse(@Val ClaimInput input, @Val Claim loaded, ClaimRepository repository)
            throws ClaimStatusNotAllowedException {
        String holder = repository.lockedBy(loaded);
        if (holder != null && !holder.equals(input.user())) {
            throw new ClaimStatusNotAllowedException("This claim is being edited by " + holder
                    + "; it cannot be edited until they save or cancel.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Refuse an edit of a claim that is no longer a DRAFT: an OPEN claim is changed by voiding it and adding a new one. */
public class RefuseNonDraftClaimEdit {
    public void refuse(@Val Claim loaded) throws ClaimStatusNotAllowedException {
        if (loaded.status() != ClaimStatus.DRAFT) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot be edited; only a DRAFT can. Void it and add a new one.");
        }
    }
}
